from pathlib import Path
import hashlib,json,subprocess
r=Path(__file__).parent
head=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()
assert not subprocess.check_output(['git','status','--porcelain'],text=True).strip()
read=lambda name:json.loads((r/name).read_text())
build=read('build-provenance.json');capture=read('capture-verdict.json');runtime=read('interactions/runtime-verdict.json');videos=read('journeys/recordings/video-manifest.json')
assert build['candidateSha']==capture['candidateSha']==runtime['candidateSha']==head
assert all(v['candidateSha']==head for v in videos)
hashes={str(p.relative_to(r)):hashlib.sha256(p.read_bytes()).hexdigest() for d in ['before','after','pairs','journeys/recordings','font-readiness'] for p in sorted((r/d).rglob('*')) if p.is_file()}
code=hashlib.sha256(json.dumps({'head':head,'build':build['sha256'],'files':hashes},sort_keys=True).encode()).hexdigest()[:16]
stories=read('story-inventory.json');journeys=read('journeys/mapping.json');checks=read('interactions/check-summary.json')
assert len(journeys)==14
m={'candidateSha':head,'evidence_code':code,'status':'incomplete: parent independent reviews and stated verification limitations remain','captureRevision':head,'buildRevision':head,'buildSha256':build['sha256'],'baselineSha':'863c687fae76c57527d495ec436afcf0ea99539a','baselineEvidenceCommit':'60ff27e35a1a772884b05d9e64141fbebc42c73c','baselineEvidenceCode':'95e2cf5e91b0fcee','publicStatus':runtime['publicStatus'],'checks':checks,'referencesAccepted':False,'source':read('source-working-tree.json'),'boardFamilies':14,'storyCount':len(stories),'stories':stories,'screenshots':capture['count'],'beforeScreenshots':len(list((r/'before').glob('*.png'))),'pairs':len(list((r/'pairs').glob('*.png'))),'absentBeforeImages':capture['missingBefore'],'videoCount':len(videos),'videoJourneys':len(videos)//2,'testViewports':runtime['viewports'],'galleryViewports':capture['viewports'],'screenshotThemes':['light','dark'],'videoThemes':['light'],'runtime':runtime,'ubuntu':read('ubuntu/verdict.json'),'hostedChecks':read('interactions/pr-final-status.json'),'journeys':journeys,'videos':videos,'fileHashes':hashes,'verificationHashes':{str(p.relative_to(r)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((r/'interactions').rglob('*')) if p.is_file()},'canonicalEvidenceHashes':{str(p.relative_to(r)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((r/'ubuntu').rglob('*')) if p.is_file()},'evidenceScripts':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in r.iterdir() if p.suffix in ['.sh','.py','.mjs']},'interactionArtifactIndex':'interactions/ARTIFACT_INDEX.md','artifactInventory':'artifact-inventory.json','archiveInventory':'archive-inventory.json','reviewInputs':'REVIEW_INPUTS.md','reviews':{'status':'parent to commission two NEW independent reviews','ratingsAssigned':False},'manualQA':False,'merged':False,'limits':['Before/after human action counts are unknown; checkpoint counts are automated assertions, not human steps.','Recordings use recorder-only pacing, not natural human timing.','No local or canonical references accepted automatically.','No live transport, persistence, live lexicon service or app-update claim from board fixtures.','Full local catalog, hosted safety, native checks, local pixels and canonical Ubuntu results are separate verdicts.','Unrepaired Numberlink republication was not rerun.']}
(r/'manifest.json').write_text(json.dumps(m,indent=2)+'\n')
print(head,code,len(hashes),'media hashes')
